export const BODY: string = "\n<p>ابعاد، ریزولوشن اور فائل سائز، تینوں عدد تصویر کے بارے میں کچھ بتاتے ہیں، مگر تینوں ایک ہی بات نہیں بتاتے۔ ان کو آپس میں گڈمڈ کرنا سب سے عام غلطی ہے، اور اسی سے اپ لوڈ مسترد ہوتے ہیں اور پرنٹ دھندلے نکلتے ہیں۔</p>\n<p>ابعاد پکسلز گنتے ہیں، ریزولوشن کثافت بتاتا ہے، اور فائل سائز ڈسک پر وزن بتاتا ہے۔ ایک عدد بدلنے سے دوسرا خود بخود نہیں بدلتا، اور یہی بات سمجھنا اس مضمون کا اصل مقصد ہے۔</p>\n<p>یہاں ہر عدد کو الگ سمجھایا گیا ہے، پھر ان کے تعلق، پرنٹ اور اسکرین کی ریاضی، اور ویب و پرنٹ کے لیے درست انتخاب بتایا گیا ہے۔ اپنی تصویر کے ابعاد جانچنے کے لیے <a href=\"/ur/tasveer-ka-size-dekhein/\">امیج ڈائمینشنز چیکر</a> استعمال کریں۔</p>\n<h2 id=\"three-different-numbers\">تین عدد، تین مطلب</h2>\n<p>ابعاد بتاتے ہیں کہ تصویر کتنے پکسلز چوڑی اور اونچی ہے۔ ریزولوشن بتاتا ہے کہ یہ پکسلز کتنے گھنے بھرے ہیں، اور فائل سائز بتاتا ہے کہ فائل کتنے کلو بائٹ یا میگا بائٹ کی ہے۔</p>\n<p>تینوں کو ایک ساتھ دیکھنا ضروری ہے۔ صرف ایک عدد دیکھ کر فیصلہ کرنا ایسے ہے جیسے کتاب کا صرف صفحات گن کر اس کا وزن اندازہ کرنا: کچھ معلومات ملتی ہے، مگر پوری کہانی نہیں۔</p>\n<h2 id=\"dimensions-explained\">ابعاد: پکسلز کی تعداد</h2>\n<p>ابعاد تصویر کی چوڑائی اور اونچائی پکسلز میں ہیں، جیسے 4000 بائی 3000۔ یہ عدد طے کرتے ہیں کہ تصویر اسکرین پر کتنی بڑی دکھائی دے گی اور پرنٹ میں کتنی جگہ لے گی۔</p>\n<p>زیادہ ابعاد کا مطلب زیادہ تفصیل کی گنجائش ہے، مگر ہمیشہ بہتر تصویر نہیں۔ اسکرین پر دکھائی جانے والی تصویر کے لیے 4000 پکسلز اکثر ضائع ہوتے ہیں، کیونکہ اسکرین خود ہی چھوٹی ہوتی ہے۔</p>\n<h2 id=\"resolution-explained\">ریزولوشن: ڈی پی آئی اور پی پی آئی</h2>\n<p>ریزولوشن پکسلز کی کثافت ہے، جو ڈی پی آئی یا پی پی آئی میں ناپی جاتی ہے۔ 300 ڈی پی آئی کا مطلب ہے کہ پرنٹ کے ہر انچ میں 300 پکسلز بھرے ہیں۔</p>\n<p>اسکرین پر ڈی پی آئی کا کوئی اثر نہیں ہوتا: براؤزر صرف پکسلز دیکھتا ہے۔ ڈی پی آئی صرف پرنٹ کے لیے اہم ہے، جہاں یہ طے کرتا ہے کہ پرنٹ کتنا تیز ہوگا۔</p>\n<h2 id=\"file-size-explained\">فائل سائز: ڈسک پر وزن</h2>\n<p>فائل سائز وہ جگہ ہے جو فائل ڈسک پر لیتی ہے، جو کلو بائٹ یا میگا بائٹ میں ناپی جاتی ہے۔ یہ ابعاد، فارمیٹ اور کمپریشن تینوں پر منحصر ہوتا ہے۔</p>\n<p>ایک ہی ابعاد کی دو تصویریں بہت مختلف فائل سائز رکھ سکتی ہیں۔ PNG اسکرین شاٹ میگا بائٹس کا ہو سکتا ہے، جبکہ اسی سائز کی JPG تصویر چند سو کلو بائٹ کی ہوتی ہے۔</p>\n<h2 id=\"how-they-relate\">تینوں عدد کیسے جڑے ہیں</h2>\n<p>ابعاد اور فائل سائز کا تعلق کمپریشن سے جڑا ہے: زیادہ پکسلز عام طور پر بڑی فائل بناتے ہیں، مگر مضبوط کمپریشن اسے چھوٹا کر سکتی ہے۔ ریزولوشن ان دونوں سے الگ میٹا ڈیٹا ہے۔</p>\n<p>ڈی پی آئی بدلنے سے پکسلز نہیں بدلتے، اس لیے فائل سائز بھی تقریباً وہی رہتا ہے۔ یہی وجہ ہے کہ ڈی پی آئی بدلنا فائل ہلکی کرنے کا طریقہ نہیں ہے۔</p>\n<h2 id=\"big-file-small-dimensions\">بڑی فائل کے ابعاد چھوٹے کیوں ہو سکتے ہیں</h2>\n<p>بڑی فائل کے چھوٹے ابعاد کی وجہ اکثر فارمیٹ ہوتا ہے۔ PNG بغیر نقصان کے کمپریس کرتا ہے، اس لیے چھوٹی PNG تصویر بھی میگا بائٹس کی ہو سکتی ہے، خاص طور پر اگر اس میں متن یا تیز کنارے ہوں۔</p>\n<p>میٹا ڈیٹا بھی وزن بڑھاتا ہے۔ کیمرے کی تصویر میں تھمب نیل اور مقام کی معلومات شامل ہو سکتی ہیں، جو فائل کو بھاری کر دیتی ہیں، حالانکہ ابعاد چھوٹے ہوں۔</p>\n<h2 id=\"small-file-huge-dimensions\">چھوٹی فائل کے ابعاد بہت بڑے کیوں ہو سکتے ہیں</h2>\n<p>چھوٹی فائل کے بڑے ابعاد کی وجہ مضبوط کمپریشن ہے۔ آسمان یا دھندلی پس منظر والی تصویر بہت اچھی طرح کمپریس ہوتی ہے، اس لیے 4000 پکسلز چوڑی تصویر بھی چند سو کلو بائٹ کی ہو سکتی ہے۔</p>\n<p>سادہ رنگ اور کم تفصیل کمپریشن کو آسان بنا دیتے ہیں۔ اس کے برعکس، پتوں یا بھیڑ والی تصویر اسی ابعاد میں کئی گنا بڑی فائل بنتی ہے۔</p>\n<h2 id=\"print-math\">پرنٹ کی ریاضی: پکسلز کو ڈی پی آئی پر تقسیم کریں</h2>\n<p>پرنٹ کا سائز نکالنے کے لیے پکسلز کو ڈی پی آئی پر تقسیم کریں۔ 3000 پکسلز چوڑی تصویر 300 ڈی پی آئی پر 10 انچ چوڑا پرنٹ دیتی ہے، اور 150 ڈی پی آئی پر 20 انچ چوڑا۔</p>\n<p>یہ حساب بتاتا ہے کہ تصویر کس سائز تک تیز پرنٹ ہوگی۔ اگر حساب سے پرنٹ آپ کی ضرورت سے چھوٹا نکلے تو تصویر کو بڑا کرنا حل نہیں، کیونکہ بڑی کی گئی تصویر دھندلی ہو جاتی ہے۔</p>\n<h2 id=\"screen-math\">اسکرین کی ریاضی: صرف پکسلز، ڈی پی آئی نظر انداز</h2>\n<p>اسکرین پر صرف پکسلز کی تعداد اہم ہے۔ 72 ڈی پی آئی اور 300 ڈی پی آئی والی ایک جیسی پکسلز والی تصویریں براؤزر میں بالکل ایک جیسی نظر آتی ہیں۔</p>\n<p>اسی لیے ویب کے لیے ڈی پی آئی بدلنا وقت ضائع کرنا ہے۔ ویب تصویر کے لیے صرف ابعاد اور فائل سائز دیکھیں، ڈی پی آئی کو پرنٹ تک چھوڑ دیں۔</p>\n<h2 id=\"compression-and-file-size\">کمپریشن اور فائل سائز</h2>\n<p>کمپریشن فائل سائز کم کرنے کا اصل طریقہ ہے۔ JPG معیار کم کر کے فائل چھوٹی کرتا ہے، جبکہ PNG بغیر نقصان کے دباؤ ڈالتا ہے اور اکثر بڑی فائل چھوڑتا ہے۔</p>\n<p>کمپریشن ابعاد نہیں بدلتی: 2000 پکسلز والی تصویر کمپریس ہو کر بھی 2000 پکسلز کی رہتی ہے۔ اس لیے فائل ہلکی کرنے کے لیے کمپریشن چنیں، اور تصویر چھوٹی کرنے کے لیے ری سائز چنیں۔</p>\n<h2 id=\"choosing-dimensions-for-web\">ویب کے لیے ابعاد چننا</h2>\n<p>ویب کے لیے تصویر اتنی بڑی ہونی چاہیے جتنی اسکرین پر دکھائی دے گی، اس سے زیادہ نہیں۔ ہیرو تصویر کے لیے 1920 پکسلز اور تھمب نیل کے لیے 400 پکسلز اکثر کافی ہوتے ہیں۔</p>\n<p>اضافی پکسلز صرف صفحہ سست کرتے ہیں۔ ہر اضافی میگا بائٹ لوڈنگ میں وقت بڑھاتا ہے، خاص طور پر موبائل ڈیٹا پر، اور وزیٹر کے انتظار کی حد بہت کم ہوتی ہے۔</p>\n<h2 id=\"choosing-dimensions-for-print\">پرنٹ کے لیے ابعاد چننا</h2>\n<p>پرنٹ کے لیے ابعاد کاغذ کے سائز اور ڈی پی آئی سے نکالیں۔ A4 پر 300 ڈی پی آئی پر صاف پرنٹ کے لیے تقریباً 2480 بائی 3508 پکسلز چاہییں۔</p>\n<p>چھوٹے پرنٹ کے لیے کم پکسلز کافی ہیں، مگر پوسٹر کے لیے ہزاروں پکسلز چاہییں۔ پرنٹ کروانے سے پہلے حساب کر لینا مہنگے دوبارہ پرنٹ سے بچاتا ہے۔</p>\n<h2 id=\"choosing-dimensions-for-social\">سوشل اور بازاروں کے لیے ابعاد چننا</h2>\n<p>سوشل پلیٹ فارم اور بازار اپنے تجویز کردہ ابعاد دیتے ہیں، جیسے پروفائل کے لیے 1000 پکسلز یا مصنوعات کی تصویر کے لیے 2000 پکسلز۔ ان سے کم تصویر دھندلی ہو جاتی ہے، اور ان سے زیادہ ضائع ہوتی ہے۔</p>\n<p>بازار کی تصویر میں زوم بھی اہم ہے: خریدار تصویر کو بڑا کر کے دیکھتا ہے، اس لیے مصنوعات کی تصویر تجویز کردہ سائز سے تھوڑی بڑی رکھنا بہتر ہوتا ہے۔</p>\n<h2 id=\"common-myths\">ابعاد، ریزولوشن اور سائز کے بارے میں عام غلط فہمیاں</h2>\n<p>ایک عام غلط فہمی یہ ہے کہ 72 ڈی پی آئی والی تصویر خراب ہوتی ہے۔ حقیقت یہ ہے کہ ڈی پی آئی اسکرین پر کچھ نہیں بدلتا، صرف پکسلز اہم ہیں۔</p>\n<p>دوسری غلط فہمی یہ ہے کہ بڑی فائل ہمیشہ بہتر تصویر ہوتی ہے۔ بڑی فائل اکثر صرف خراب کمپریشن یا غیر ضروری میٹا ڈیٹا کی وجہ سے بڑی ہوتی ہے، بہتر تفصیل کی وجہ سے نہیں۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: کون سا عدد کہاں اہم ہے</h2>\n<p>ویب پر ابعاد اور فائل سائز دیکھیں، ڈی پی آئی بھول جائیں۔ پرنٹ پر ابعاد اور ڈی پی آئی دونوں دیکھیں، فائل سائز ثانوی ہے۔ سوشل میڈیا پر پلیٹ فارم کی تجویز کردہ ابعاد سب سے اہم ہیں۔</p>\n<p>شک ہو تو <a href=\"/ur/blog/tasveer-dimensions-kaise-check-karein/\">تصویر کے ابعاد کیسے جانچیں</a> پڑھیں اور اپنی تصویر <a href=\"/ur/blog/tasveer-dimensions-checker-rehnumai/\">ڈائمینشنز چیکر رہنما</a> سے جانچیں۔ ڈی پی آئی بدلنا ہو تو <a href=\"/ur/tasveer-ka-dpi-badlein/\">امیج ڈی پی آئی چینجر</a> کام آئے گا۔</p>\n";

